div.script:
                                // Automatically load upcoming lessons on page load
                                document.addEventListener("DOMContentLoaded", function () {
                                    loadUpcomingLessons();
                                });

                                function loadUpcomingLessons(page = 1) {
                                    fetch(`/my_dashboard/upcoming-lessons?page=${page}`)
                                        .then(response => response.text())
                                        .then(html => {
                                            document.getElementById('upcoming-lessons-content').innerHTML = html;

                                            // Add event listeners to the pagination links
                                            const paginationLinks = document.querySelectorAll('#upcoming-lessons-content .page-link');
                                            paginationLinks.forEach(link => {
                                                link.addEventListener('click', function (event) {
                                                    event.preventDefault();
                                                    const newPage = parseInt(new URL(this.href).searchParams.get('page'));
                                                    loadUpcomingLessons(newPage);
                                                });
                                            });
                                        })
                                        .catch(error => {
                                            console.error('Error loading upcoming lessons:', error);
                                        });
                                }

                                function loadCompletedLessons(page = 1) {
                                    fetch(`/my_dashboard/completed-lessons?page=${page}`)
                                        .then(response => response.text())
                                        .then(html => {
                                            document.getElementById('completed-lessons-content').innerHTML = html;

                                            // Add event listeners to the pagination links
                                            const paginationLinks = document.querySelectorAll('#completed-lessons-content .page-link');
                                            paginationLinks.forEach(link => {
                                                link.addEventListener('click', function (event) {
                                                    event.preventDefault();
                                                    const newPage = parseInt(new URL(this.href).searchParams.get('page'));
                                                    loadCompletedLessons(newPage);
                                                });
                                            });
                                        })
                                        .catch(error => {
                                            console.error('Error loading completed lessons:', error);
                                        });
                                }
